
  create table "public"."bolos" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "bolo_imagem" text,
    "topper_imagem" text,
    "peso" double precision,
    "forma" character varying,
    "massa" text,
    "recheio" text,
    "cobertura" text,
    "tema" text,
    "descricao" text,
    "detalhamento_topper" text,
    "dono_do_bolo" uuid not null default auth.uid()
      );


alter table "public"."bolos" enable row level security;


  create table "public"."classes" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "tipo" text not null
      );


alter table "public"."classes" enable row level security;


  create table "public"."pedidos" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "descricao" text,
    "bolo_id" bigint,
    "produto_id" bigint,
    "usuario_id" uuid,
    "status" text,
    "quantidade" bigint
      );


alter table "public"."pedidos" enable row level security;


  create table "public"."produtos" (
    "id" bigint generated by default as identity not null,
    "created_at" timestamp with time zone not null default now(),
    "nome" character varying not null,
    "tipo" bigint not null,
    "descricao" text,
    "imagem" text,
    "preco" double precision
      );


alter table "public"."produtos" enable row level security;


  create table "public"."user_roles" (
    "id" uuid not null default gen_random_uuid(),
    "user_id" uuid not null,
    "role" text not null,
    "created_at" timestamp without time zone default now(),
    "cpf" text,
    "email" character varying
      );


alter table "public"."user_roles" enable row level security;

CREATE UNIQUE INDEX bolos_pkey ON public.bolos USING btree (id);

CREATE UNIQUE INDEX classes_pkey ON public.classes USING btree (id);

CREATE INDEX idx_user_roles_user_id ON public.user_roles USING btree (user_id);

CREATE UNIQUE INDEX pedidos_pkey ON public.pedidos USING btree (id);

CREATE UNIQUE INDEX produtos_pkey ON public.produtos USING btree (id);

CREATE UNIQUE INDEX user_roles_cpf_key ON public.user_roles USING btree (cpf);

CREATE UNIQUE INDEX user_roles_email_key ON public.user_roles USING btree (email);

CREATE UNIQUE INDEX user_roles_pkey ON public.user_roles USING btree (id);

CREATE UNIQUE INDEX user_roles_user_id_role_key ON public.user_roles USING btree (user_id, role);

alter table "public"."bolos" add constraint "bolos_pkey" PRIMARY KEY using index "bolos_pkey";

alter table "public"."classes" add constraint "classes_pkey" PRIMARY KEY using index "classes_pkey";

alter table "public"."pedidos" add constraint "pedidos_pkey" PRIMARY KEY using index "pedidos_pkey";

alter table "public"."produtos" add constraint "produtos_pkey" PRIMARY KEY using index "produtos_pkey";

alter table "public"."user_roles" add constraint "user_roles_pkey" PRIMARY KEY using index "user_roles_pkey";

alter table "public"."bolos" add constraint "bolos_dono_do_bolo_fkey" FOREIGN KEY (dono_do_bolo) REFERENCES auth.users(id) ON DELETE CASCADE not valid;

alter table "public"."bolos" validate constraint "bolos_dono_do_bolo_fkey";

alter table "public"."pedidos" add constraint "pedidos_bolo_id_fkey" FOREIGN KEY (bolo_id) REFERENCES public.bolos(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "public"."pedidos" validate constraint "pedidos_bolo_id_fkey";

alter table "public"."pedidos" add constraint "pedidos_produto_id_fkey" FOREIGN KEY (produto_id) REFERENCES public.produtos(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "public"."pedidos" validate constraint "pedidos_produto_id_fkey";

alter table "public"."pedidos" add constraint "pedidos_usuario_id_fkey" FOREIGN KEY (usuario_id) REFERENCES auth.users(id) ON UPDATE CASCADE ON DELETE CASCADE not valid;

alter table "public"."pedidos" validate constraint "pedidos_usuario_id_fkey";

alter table "public"."produtos" add constraint "produtos_tipo_check" CHECK ((tipo > 0)) not valid;

alter table "public"."produtos" validate constraint "produtos_tipo_check";

alter table "public"."produtos" add constraint "produtos_tipo_fkey" FOREIGN KEY (tipo) REFERENCES public.classes(id) not valid;

alter table "public"."produtos" validate constraint "produtos_tipo_fkey";

alter table "public"."user_roles" add constraint "user_roles_cpf_key" UNIQUE using index "user_roles_cpf_key";

alter table "public"."user_roles" add constraint "user_roles_email_key" UNIQUE using index "user_roles_email_key";

alter table "public"."user_roles" add constraint "user_roles_user_id_fkey" FOREIGN KEY (user_id) REFERENCES auth.users(id) ON DELETE CASCADE not valid;

alter table "public"."user_roles" validate constraint "user_roles_user_id_fkey";

alter table "public"."user_roles" add constraint "user_roles_user_id_role_key" UNIQUE using index "user_roles_user_id_role_key";

set check_function_bodies = off;

CREATE OR REPLACE FUNCTION public.check_if_admin()
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
AS $function$
begin
  return exists(
    select 1 from public.user_roles where user_id = auth.uid() and role = 'admin'
  );

  end;

  $function$
;

