  create policy "Usuários autenticados podem criar bolos"
  on "public"."bolos"
  as permissive
  for insert
  to authenticated
with check ((auth.uid() = dono_do_bolo));



  create policy "Usuários autenticados podem ver todos os bolos"
  on "public"."bolos"
  as permissive
  for select
  to authenticated
using (true);



  create policy "Usuários podem deletar apenas seus próprios bolos"
  on "public"."bolos"
  as permissive
  for delete
  to authenticated
using ((auth.uid() = dono_do_bolo));



  create policy "Usuários podem editar apenas seus próprios bolos"
  on "public"."bolos"
  as permissive
  for update
  to authenticated
using ((auth.uid() = dono_do_bolo))
with check ((auth.uid() = dono_do_bolo));



  create policy "Enable read access for all users"
  on "public"."classes"
  as permissive
  for select
  to public
using (true);



  create policy "admin_sees_all_pedidos"
  on "public"."pedidos"
  as permissive
  for select
  to authenticated
using ((EXISTS ( SELECT 1
   FROM public.user_roles
  WHERE ((pedidos.usuario_id = auth.uid()) AND (user_roles.role = ANY (ARRAY['admin'::text, 'super_admin'::text]))))));



  create policy "admin_updates_pedidos"
  on "public"."pedidos"
  as permissive
  for update
  to authenticated
using ((EXISTS ( SELECT 1
   FROM public.user_roles
  WHERE ((pedidos.usuario_id = auth.uid()) AND (user_roles.role = 'admin'::text)))))
with check ((EXISTS ( SELECT 1
   FROM public.user_roles
  WHERE ((pedidos.usuario_id = auth.uid()) AND (user_roles.role = 'admin'::text)))));



  create policy "user_inserts_own_pedidos"
  on "public"."pedidos"
  as permissive
  for insert
  to authenticated
with check ((auth.uid() = usuario_id));



  create policy "user_sees_own_pedidos"
  on "public"."pedidos"
  as permissive
  for select
  to authenticated
using ((auth.uid() = usuario_id));



