using (public.check_if_admin())
with check (public.check_if_admin());



  create policy "user_SELECT_own_email_cpf"
  on "public"."user_roles"
  as permissive
  for select
  to authenticated
using (((auth.uid() = user_id) AND (NOT public.check_if_admin())));



  create policy "user_delete_own_email_cpf"
  on "public"."user_roles"
  as permissive
  for delete
  to authenticated
using (((auth.uid() = user_id) AND (NOT public.check_if_admin())));



  create policy "user_update_own_email_cpf"
  on "public"."user_roles"
  as permissive
  for update
  to authenticated
using (((auth.uid() = user_id) AND (NOT public.check_if_admin())))
with check (((auth.uid() = user_id) AND (role = ( SELECT user_roles_1.role
   FROM public.user_roles user_roles_1
  WHERE (user_roles_1.user_id = auth.uid())))));



